// src/features/Sales/pages/PurchasesManagement.jsx
import React, { useState } from 'react';
import {
  Container,
  Typography,
  Divider,
  Box,
  Tabs,
  Tab,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Button,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Grid,
  IconButton,
  FormControl,
  InputLabel,
  Select,
  MenuItem
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import CloseIcon from '@mui/icons-material/Close';

// Función local para formatear moneda
const formatCurrency = (value) => {
  return new Intl.NumberFormat('es-MX', {
    style: 'currency',
    currency: 'MXN'
  }).format(value || 0);
};

// Función local para formatear fecha
const formatDate = (dateString) => {
  if (!dateString) return 'N/A';
  
  const date = new Date(dateString);
  return date.toLocaleDateString('es-MX', {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  });
};

const PurchasesManagement = () => {
  const [tabValue, setTabValue] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [openPurchaseForm, setOpenPurchaseForm] = useState(false);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };
  
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleOpenPurchaseForm = () => {
    setOpenPurchaseForm(true);
  };

  const handleClosePurchaseForm = () => {
    setOpenPurchaseForm(false);
  };

  // Datos de ejemplo para compras
  const purchases = [
    { id: 1, date: '2023-05-05', supplier: 'Proveedor A', reference: 'PO-001', total: 5000, status: 'Recibido' },
    { id: 2, date: '2023-05-10', supplier: 'Proveedor B', reference: 'PO-002', total: 3500, status: 'Pendiente' },
    { id: 3, date: '2023-05-15', supplier: 'Proveedor C', reference: 'PO-003', total: 2800, status: 'Recibido' },
    { id: 4, date: '2023-05-20', supplier: 'Proveedor A', reference: 'PO-004', total: 1200, status: 'Cancelado' }
  ];

  // Datos de ejemplo para proveedores
  const suppliers = [
    { id: 1, name: 'Proveedor A', email: 'proveedora@example.com', phone: '555-1234', contactPerson: 'Juan Pérez', lastOrder: '2023-05-05' },
    { id: 2, name: 'Proveedor B', email: 'proveedorb@example.com', phone: '555-5678', contactPerson: 'María López', lastOrder: '2023-05-10' },
    { id: 3, name: 'Proveedor C', email: 'proveedorc@example.com', phone: '555-9012', contactPerson: 'Carlos Gómez', lastOrder: '2023-05-15' }
  ];

  const getStatusColor = (status) => {
    switch (status) {
      case 'Recibido':
        return 'success';
      case 'Pendiente':
        return 'warning';
      case 'Cancelado':
        return 'error';
      default:
        return 'default';
    }
  };

  // Componente de Tabla de Compras
  const PurchaseTable = () => (
    <Paper sx={{ p: 2, width: '100%' }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6">Órdenes de Compra</Typography>
        
        <Button
          variant="contained"
          color="primary"
          startIcon={<AddIcon />}
          onClick={handleOpenPurchaseForm}
        >
          Nueva Compra
        </Button>
      </Box>
      
      <TableContainer>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>ID</TableCell>
              <TableCell>Fecha</TableCell>
              <TableCell>Proveedor</TableCell>
              <TableCell>Referencia</TableCell>
              <TableCell align="right">Total</TableCell>
              <TableCell align="center">Estado</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {purchases.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage).map((purchase) => (
              <TableRow key={purchase.id}>
                <TableCell>{purchase.id}</TableCell>
                <TableCell>{formatDate(purchase.date)}</TableCell>
                <TableCell>{purchase.supplier}</TableCell>
                <TableCell>{purchase.reference}</TableCell>
                <TableCell align="right">{formatCurrency(purchase.total)}</TableCell>
                <TableCell align="center">
                  <Chip 
                    label={purchase.status}
                    color={getStatusColor(purchase.status)}
                    size="small"
                  />
                </TableCell>
              </TableRow>
            ))}
            {purchases.length === 0 && (
              <TableRow>
                <TableCell colSpan={6} align="center">
                  No hay compras registradas
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>
      
      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={purchases.length}
        rowsPerPage={rowsPerPage}
        page={page}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
      />
    </Paper>
  );

  // Componente de Lista de Proveedores
  const SupplierList = () => (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6">Proveedores</Typography>
        
        <Button
          variant="contained"
          color="primary"
          startIcon={<AddIcon />}
          size="small"
        >
          Nuevo Proveedor
        </Button>
      </Box>
      
      <TableContainer>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>Nombre</TableCell>
              <TableCell>Email</TableCell>
              <TableCell>Teléfono</TableCell>
              <TableCell>Contacto</TableCell>
              <TableCell>Última Compra</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {suppliers.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage).map((supplier) => (
              <TableRow key={supplier.id}>
                <TableCell>{supplier.name}</TableCell>
                <TableCell>{supplier.email}</TableCell>
                <TableCell>{supplier.phone}</TableCell>
                <TableCell>{supplier.contactPerson}</TableCell>
                <TableCell>{formatDate(supplier.lastOrder)}</TableCell>
              </TableRow>
            ))}
            {suppliers.length === 0 && (
              <TableRow>
                <TableCell colSpan={5} align="center">
                  No hay proveedores registrados
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>
      
      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={suppliers.length}
        rowsPerPage={rowsPerPage}
        page={page}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
      />
    </Box>
  );

  // Componente de Formulario de Compra
  const PurchaseForm = () => (
    <Dialog 
      open={openPurchaseForm} 
      onClose={handleClosePurchaseForm}
      fullWidth
      maxWidth="md"
    >
      <DialogTitle>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          Nueva Orden de Compra
          <IconButton onClick={handleClosePurchaseForm}>
            <CloseIcon />
          </IconButton>
        </Box>
      </DialogTitle>
      
      <DialogContent dividers>
        <Grid container spacing={2}>
          <Grid item xs={12} sm={6}>
            <FormControl fullWidth>
              <InputLabel id="supplier-label">Proveedor</InputLabel>
              <Select
                labelId="supplier-label"
                label="Proveedor"
                defaultValue=""
              >
                <MenuItem value="Proveedor A">Proveedor A</MenuItem>
                <MenuItem value="Proveedor B">Proveedor B</MenuItem>
                <MenuItem value="Proveedor C">Proveedor C</MenuItem>
              </Select>
            </FormControl>
          </Grid>
          
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Referencia"
              required
            />
          </Grid>
          
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Fecha"
              type="date"
              defaultValue={new Date().toISOString().split('T')[0]}
              InputLabelProps={{ shrink: true }}
              required
            />
          </Grid>
          
          <Grid item xs={12} sm={6}>
            <FormControl fullWidth>
              <InputLabel id="status-label">Estado</InputLabel>
              <Select
                labelId="status-label"
                label="Estado"
                defaultValue="Pendiente"
              >
                <MenuItem value="Pendiente">Pendiente</MenuItem>
                <MenuItem value="Recibido">Recibido</MenuItem>
                <MenuItem value="Cancelado">Cancelado</MenuItem>
              </Select>
            </FormControl>
          </Grid>
          
          <Grid item xs={12}>
            <Typography variant="subtitle1" gutterBottom>
              Productos (Versión simplificada)
            </Typography>
            <TextField
              fullWidth
              label="Descripción"
              multiline
              rows={3}
            />
          </Grid>
          
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Total"
              type="number"
              InputProps={{ inputProps: { min: 0, step: 0.01 } }}
              required
            />
          </Grid>
        </Grid>
      </DialogContent>
      
      <DialogActions>
        <Button onClick={handleClosePurchaseForm}>
          Cancelar
        </Button>
        <Button
          variant="contained"
          color="primary"
        >
          Guardar Compra
        </Button>
      </DialogActions>
    </Dialog>
  );

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Gestión de Compras
      </Typography>
      <Divider sx={{ mb: 4 }} />

      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
        <Tabs value={tabValue} onChange={handleTabChange} aria-label="purchases tabs">
          <Tab label="Órdenes de Compra" />
          <Tab label="Proveedores" />
        </Tabs>
      </Box>

      <Box sx={{ mt: 2 }}>
        {tabValue === 0 && <PurchaseTable />}
        {tabValue === 1 && <SupplierList />}
      </Box>

      <PurchaseForm />
    </Container>
  );
};

export default PurchasesManagement;